UPDATE up_sync SET sync_status = #{syncStatus}, process_time = NOW() WHERE batch_uuid IN
#{batchUuid}
AND sync_status = 0

UPDATE up_sync
SET retry_count = retry_count + 1
WHERE id = #{id}

UPDATE up_sync
SET sync_status = #{syncStatus},
    process_time = NOW(),
    error_msg = #{errorMsg}
WHERE id = #{id}
  AND sync_status = 0
